window.__VP_HASH_MAP__=JSON.parse("{\"archives.md\":\"CqREBgyl\",\"category_index.md\":\"P9AuFYGU\",\"category_子文章.md\":\"DY6kJmBk\",\"category_散文.md\":\"Ds-XU_lO\",\"category_文章.md\":\"PspK8LzT\",\"docs_doc1.md\":\"aiBAA1sy\",\"docs_doc2.md\":\"CQjpf4aV\",\"docs_doc3.md\":\"DNh1fTtP\",\"docs_doc4.md\":\"Y9C1kQ5y\",\"docs_doc5.md\":\"BZm8OEmI\",\"essays_066678.md\":\"DzQTjHUz\",\"essays_1eeaa2.md\":\"inW8nR39\",\"essays_2f010d.md\":\"YDLgPcst\",\"essays_48e10b.md\":\"Cm7ppvN4\",\"essays_67ca45.md\":\"DrKvb5la\",\"essays_7e8597.md\":\"udp9n8BF\",\"essays_7ea8f9.md\":\"LWkLWhaW\",\"essays_7f60e9.md\":\"nZ0C-sb3\",\"essays_8cc488.md\":\"qyOLj_Ta\",\"essays_9743b6.md\":\"BLQ86L9H\",\"essays_index.md\":\"D2tcsXLx\",\"essays_page-2.md\":\"HXayYiJS\",\"index.md\":\"DOoNQdAg\",\"page-1.md\":\"Bvy5wuPw\",\"page-2.md\":\"DlQqhxCW\",\"posts_10.md\":\"CTCPhpCw\",\"posts_59961a.md\":\"B4JDDEeq\",\"posts_6.md\":\"6LZs3TKZ\",\"posts_60a79d.md\":\"BB0nGR4d\",\"posts_8.md\":\"BVd4RopK\",\"posts_9.md\":\"DLl_xJKz\",\"posts_a61a93.md\":\"Fio_ebmW\",\"posts_e9f520.md\":\"Mr7c_A5Y\",\"posts_ff90c3.md\":\"DRuBhBY3\",\"tags_index.md\":\"EShM6ExB\",\"tags_一杯茶的时光.md\":\"DRr3STE-\",\"tags_一次难忘的午餐.md\":\"GFyznVwl\",\"tags_四季.md\":\"T0PAIwcV\",\"tags_感悟.md\":\"BJKgN9sr\",\"tags_慢调.md\":\"MW6uPJXA\",\"tags_旅行的意义.md\":\"BSiTRY5R\",\"tags_旅途.md\":\"gv1uYbLX\",\"tags_温暖.md\":\"D5cqiBfb\",\"tags_生活.md\":\"CWNQsbwJ\",\"tags_生活中的小确幸.md\":\"Wl2-xweH\",\"tags_短暂的宁静.md\":\"CPadVaql\",\"tags_自然.md\":\"DVO_c0hf\",\"tags_观察.md\":\"BnWQ60ob\",\"tags_观察日常.md\":\"DbklX-_C\",\"tags_记忆.md\":\"jLHYG-V7\",\"tags_运动的乐趣.md\":\"UoY1eWoi\",\"tags_阅读.md\":\"L0o3B1tA\",\"tags_阅读的乐趣.md\":\"8gJZ5fB3\",\"tags_随笔.md\":\"CjCqu_vj\"}");window.__VP_SITE_DATA__=JSON.parse("{\"lang\":\"en-US\",\"dir\":\"ltr\",\"title\":\"只抄\",\"titleTemplate\":\"VitePress Theme Minimalism\",\"description\":\"VitePress Theme Minimalism\",\"base\":\"/\",\"head\":[],\"router\":{\"prefetchLinks\":true},\"appearance\":true,\"themeConfig\":{\"posts\":[{\"order\":1,\"pinned\":\"置顶\",\"id\":\"59961a\",\"title\":\"1.生活中的小确幸（自定义摘要）\",\"datetime\":\"2023-10-01 10:00:00\",\"outline\":\"deep\",\"description\":\"摘要 摘要 摘要 摘要 摘要\",\"category\":\"文章\",\"tags\":[\"生活中的小确幸\"],\"permalink\":\"/posts/59961a\",\"folder\":\"posts\",\"excerpt\":\"摘要 摘要 摘要 摘要 摘要\"},{\"order\":2,\"id\":\"a61a93\",\"title\":\"2.旅行的意义（密码：123456）\",\"datetime\":\"2023-10-02 10:00:00\",\"outline\":\"deep\",\"category\":\"文章\",\"tags\":[\"旅行的意义\"],\"permalink\":\"/posts/a61a93\",\"folder\":\"posts\",\"excerpt\":\"🔒 此内容已加密\"},{\"id\":\"066678\",\"order\":2,\"pinned\":\"置顶\",\"title\":\"春日微风\",\"datetime\":\"2026-10-01 10:00:00\",\"category\":\"散文\",\"tags\":[\"随笔\",\"四季\"],\"permalink\":\"/essays/066678\",\"folder\":\"essays\",\"excerpt\":\"清晨推开窗，空气里带着一丝若有若无的花草清香。那是初春特有的味道，料峭的寒意刚刚散去，微风轻柔得像是春水漫过指尖。 阳光透过树叶的缝隙洒下来，在石板路上映出斑驳的光影。远处的柳枝吐出新芽，嫩绿嫩绿的，在风中轻轻摇曳。巷子里传来几声清脆的鸟鸣，打破了清晨的静谧，却让人倍感安宁。生活大概就该是这样吧，不\"},{\"id\":\"48e10b\",\"title\":\"岁月如流，静水深流\",\"datetime\":\"2026-10-10 10:00:00\",\"category\":\"散文\",\"tags\":[\"感悟\",\"随笔\"],\"permalink\":\"/essays/48e10b\",\"folder\":\"essays\",\"excerpt\":\"站在江边望去，江水滔滔东去，水面平缓如镜，水底却暗流涌动。子在川上曰：“逝者如斯夫，不舍昼夜。” 年少时总以为日子漫长得望不到头，总渴望早些奔向未知的远方与精彩。直到某一天猛然回首，才发现青春已然悄悄翻过了几个篇章，许多故人已经天各一方。时间从不为任何人驻足，但它却温柔地抚平了许多往昔的棱角与执念。\"},{\"id\":\"7e8597\",\"title\":\"冬夜围炉漫谈\",\"datetime\":\"2026-10-09 10:00:00\",\"category\":\"散文\",\"tags\":[\"生活\",\"温暖\"],\"permalink\":\"/essays/7e8597\",\"folder\":\"essays\",\"excerpt\":\"窗外寒风呼啸，屋内的炭火炉却泛着红润温吞的光芒。炉铁网架上烤着红薯与年糕，偶尔发出滋滋的微响，焦香四溢。 三两知己围坐炉旁，烫上一壶黄酒，无需刻意寻找话题，想到什么便聊什么。从年少时的荒唐梦想，到人到中年的现实羁绊，言语在热气氤氲中变得柔和起来。生活的底色虽然免不了有严寒与奔波，但只要心头有一处能让\"},{\"id\":\"7ea8f9\",\"title\":\"秋叶落下的声音\",\"datetime\":\"2026-10-08 10:00:00\",\"category\":\"散文\",\"tags\":[\"四季\",\"感悟\"],\"permalink\":\"/essays/7ea8f9\",\"folder\":\"essays\",\"excerpt\":\"秋风起时，落叶便成了一场盛大的告别。一片金黄的银杏叶脱离枝头，在空中打了几个旋儿，最终轻轻落在泥土上。 那声音极轻微，若非屏息凝神，几乎无法察觉。人们常悲秋，叹落叶飘零、草木枯槁，但大自然从不曾真正哀叹消亡。凋零并非终点，而是生命另一种形式的回归与馈赠，化作春泥更护花。树木褪去繁茂的枝叶，是为了熬过\"},{\"id\":\"9743b6\",\"title\":\"巷子深处的旧书店\",\"datetime\":\"2026-10-07 10:00:00\",\"category\":\"散文\",\"tags\":[\"记忆\",\"阅读\"],\"permalink\":\"/essays/9743b6\",\"folder\":\"essays\",\"excerpt\":\"在老街深处拐弯的地方，藏着一家不起眼的旧书店。窄小的门面，褪色的木质招牌，推开门时门铃会发出清脆叮当声。 书店里弥漫着陈年纸张与油墨特有的木质香气，书架高耸直抵天花板，各类书籍层层叠叠。这里的书虽然封面泛黄，页脚带着翻阅的折痕，却沉淀着时光与往昔读者的温度。偶有一页夹着泛旧的车票或干枯的书签，总让人\"},{\"id\":\"1eeaa2\",\"title\":\"黄昏时分的归鸟\",\"datetime\":\"2026-10-06 10:00:00\",\"category\":\"散文\",\"tags\":[\"自然\",\"随笔\"],\"permalink\":\"/essays/1eeaa2\",\"folder\":\"essays\",\"excerpt\":\"天际渐渐由橙黄转为暗蓝，落日沉入地平线只余下一抹余晖。几只飞鸟掠过高空，排成整齐的雁阵，振翅向南飞去。 它们的身影在天幕上被拉得很长很细，伴随着几声清厉的啼鸣，迅速消失在山峦与树林的尽头。每当看到归鸟的时刻，心头总会升起一种莫名的归属感。无论是奔波在外的游子，还是辛劳了一天的普通人，在这个时刻都渴望\"},{\"id\":\"7f60e9\",\"title\":\"午后的一杯清茶\",\"datetime\":\"2026-10-05 10:00:00\",\"category\":\"散文\",\"tags\":[\"生活\",\"慢调\"],\"permalink\":\"/essays/7f60e9\",\"folder\":\"essays\",\"excerpt\":\"午后三点，阳光恰好斜斜地落在茶桌的一角。烧上一壶山泉水，取少许白茶投入白瓷杯中，静候水沸。 水注倾泻入杯的瞬间，干燥的茶叶在热水中翻滚舒展，茶香随之袅袅升起。初品微苦，继而甘醇从舌根缓缓蔓延开来，回味悠长。在这个事事追求效率与反馈的时代，能够慢下节奏，用半个小时认真泡一杯茶，已然成了一种难得的奢侈。\"},{\"id\":\"8cc488\",\"title\":\"远山如黛\",\"datetime\":\"2026-10-04 10:00:00\",\"category\":\"散文\",\"tags\":[\"旅途\",\"自然\"],\"permalink\":\"/essays/8cc488\",\"folder\":\"essays\",\"excerpt\":\"傍晚车行至郊野，天边云霞漫卷，将整片天际染上了淡紫与胭红。远方的连绵山峦在暮色笼罩下，隐隐透出深邃的青黛色。 没有城市的霓虹喧嚣，没有车水马龙的鸣笛，眼前的天地浩大而纯粹。山势起伏如水墨画卷中的淡墨皴擦，虚实相生，意境悠远。车窗外的晚风微凉，吹拂着衣襟与发梢，带走了一整周积累的浮躁与疲惫。面对这千百\"},{\"id\":\"2f010d\",\"title\":\"窗前的老槐树\",\"datetime\":\"2026-10-03 10:00:00\",\"category\":\"散文\",\"tags\":[\"记忆\",\"生活\"],\"permalink\":\"/essays/2f010d\",\"folder\":\"essays\",\"excerpt\":\"书房的窗前有一棵老槐树，枝桠舒展，树冠遮盖了大半个庭院。每年初夏，洁白的槐花便成串成串地挂满枝头，满院飘香。 记忆里，祖母总会在这时候拿着长竿打下新鲜的槐花，洗净后拌上面粉蒸成槐花饭。那是童年里最朴实也最难以忘怀的清甜滋味。时光匆匆流转，许多老房子渐渐拆迁改造，唯独这棵老槐树依然静默地伫立在岁月里，\"},{\"id\":\"67ca45\",\"index\":true,\"title\":\"雨后的青苔\",\"datetime\":\"2026-10-02 10:00:00\",\"category\":\"散文\",\"tags\":[\"随笔\",\"观察\"],\"permalink\":\"/essays/67ca45\",\"folder\":\"essays\",\"excerpt\":\"一场绵绵细雨下了整整两日，终于在午后放晴。空气湿漉漉的，草木吸饱了水分，呈现出格外饱满的色泽。 走到院落角落的石阶旁，忽见背阴处悄然蔓延出一片绒绒的青绿。那是青苔，不争春光，不喧宾夺主，只在寂静处自顾自地生长。它们细小微茫，却聚成一片如丝绒般的地毯，覆在黝黑湿润的石面上。古人说“苔花如米小，也学牡丹\"},{\"id\":\"a60679\",\"title\":\"10.一杯茶的时光（手动摘要）（自定义容器）\",\"datetime\":\"2023-10-10 10:00:00\",\"permalink\":\"/posts/10\",\"outline\":\"deep\",\"category\":\"子文章\",\"tags\":[\"一杯茶的时光\"],\"folder\":\"posts\",\"excerpt\":\"泡一杯茶，静待水开，是我最喜欢的放松方式。\"},{\"id\":\"fc8a2a\",\"title\":\"8.短暂的宁静（文章 9 已隐藏，需直接访问 /posts/9 ）\",\"datetime\":\"2023-10-08 10:00:00\",\"permalink\":\"/posts/8\",\"outline\":\"deep\",\"category\":\"子文章\",\"tags\":[\"短暂的宁静\"],\"folder\":\"posts\",\"excerpt\":\"有时，生活的喧嚣让我渴望一份宁静。今天，我在阳台上静静坐着，听着远处的鸟鸣，感受着微风拂面。这样的片刻让我意识到，繁忙并不是生活的全部，内心的平静才是真正的幸福。在这个快节奏的时代，给自己留点时间去思考，去感受生活的美好是多么重要。短暂的宁静让我重新审视生活，找到内心的平衡。那些简单而平静的时光，正\"},{\"id\":\"3a5d0c\",\"title\":\"6.运动的乐趣（文章 7 为草稿，无法访问）\",\"datetime\":\"2023-10-06 10:00:00\",\"permalink\":\"/posts/6\",\"outline\":\"deep\",\"category\":\"子文章\",\"tags\":[\"运动的乐趣\"],\"folder\":\"posts\",\"excerpt\":\"运动是一种解压的方式。每当我感到疲惫时，我都会选择去健身房锻炼。跑步机上的每一步，似乎都能将我的烦恼抛在脑后，心中充满了畅快的感觉。锻炼不仅让我保持身体健康，也让我在挥汗如雨中找到了快乐。和朋友一起去打篮球的时光，更是让我感受到团队合作的力量。在运动中，我结识了许多志同道合的伙伴，分享着彼此的目标与\"},{\"id\":\"60a79d\",\"title\":\"5.观察日常\",\"datetime\":\"2023-10-05 10:00:00\",\"outline\":\"deep\",\"category\":\"文章\",\"tags\":[\"观察日常\"],\"permalink\":\"/posts/60a79d\",\"folder\":\"posts\",\"excerpt\":\"在日常生活中，观察周围的细节总能让我有所收获。今天，我在地铁上看到一个小女孩对窗外的景物充满好奇，眼神中闪烁着纯真的光芒。她指着窗外的建筑，兴奋地和妈妈交流，那种纯粹的快乐感染了我。这让我意识到，生活中的美好往往藏在那些看似平常的瞬间里。用心去观察，每一天都有新发现，仿佛打开了一扇窗，让我看到了不一\"},{\"id\":\"e9f520\",\"title\":\"4.一次难忘的午餐\",\"datetime\":\"2023-10-04 10:00:00\",\"outline\":\"deep\",\"category\":\"文章\",\"tags\":[\"一次难忘的午餐\"],\"permalink\":\"/posts/e9f520\",\"folder\":\"posts\",\"excerpt\":\"昨天，我和朋友一起去了一家新开的餐厅。食物色香味俱全，特别是那道招牌菜，令人垂涎欲滴。我们一边享受美食，一边聊着生活中的琐事，时光在欢声笑语中悄然流逝。餐厅的环境舒适，装饰别致，让我们放松了心情。每一次的聚餐都是一次美好的体验，让我感受到朋友之间的温暖。这次午餐不仅让我们的味蕾得到了满足，也加深了彼\"},{\"id\":\"ff90c3\",\"title\":\"3.阅读的乐趣\",\"datetime\":\"2023-10-03 10:00:00\",\"outline\":\"deep\",\"category\":\"文章\",\"tags\":[\"阅读的乐趣\"],\"permalink\":\"/posts/ff90c3\",\"folder\":\"posts\",\"excerpt\":\"阅读是一种奇妙的体验。翻开一本书，就像打开了一个新的世界。我最近在读一本关于人类历史的书，书中的故事让我对过去有了更深的理解。作者用生动的语言描绘了历史事件和人物，使我仿佛亲身经历了那些时刻。无论是小说还是非小说，阅读总能让我在想象中飞翔，心灵得到滋养。书籍是我最忠实的朋友，伴我度过无数个孤独的夜晚\"}],\"page\":{\"max\":5},\"transition\":true,\"logo\":\"/profile.png\",\"outline\":{\"level\":2},\"nav\":[{\"text\":\"首页\",\"link\":\"/\"},{\"text\":\"文章\",\"link\":\"/page-1\"},{\"text\":\"散文\",\"link\":\"/essays\"},{\"text\":\"分类\",\"link\":\"/category/\"},{\"text\":\"标签\",\"link\":\"/tags/\"},{\"text\":\"归档\",\"link\":\"/archives\"},{\"text\":\"文档\",\"link\":\"/docs/doc1\"}],\"sidebar\":{\"/docs\":[{\"text\":\"如何使用电饭煲\",\"items\":[{\"text\":\"选择合适的电饭煲\",\"link\":\"/docs/doc1\"},{\"text\":\"煮出松软米饭的技巧\",\"link\":\"/docs/doc2\"},{\"text\":\"电饭煲的多功能用途\",\"link\":\"/docs/doc3\"},{\"text\":\"电饭煲的清洁与保养\",\"link\":\"/docs/doc4\"},{\"text\":\"电饭煲常见问题处理\",\"link\":\"/docs/doc5\"}]}]},\"socialLinks\":[{\"icon\":\"github\",\"link\":\"https://github.com/izhichao/vitepress-theme-minimalism\"}],\"footer\":{\"message\":\"Theme by <a href=\\\"https://github.com/izhichao/vitepress-theme-minimalism\\\" target=\\\"_blank\\\">Minimalism</a>\",\"copyright\":\"Copyright © 2017-2026 <a href=\\\"https://github.com/izhichao\\\" target=\\\"_blank\\\">只抄</a>\"},\"search\":{\"provider\":\"local\"}},\"locales\":{},\"cleanUrls\":true,\"additionalConfig\":{}}");